export class OIDCApi extends BaseAPI implements OIDCApiInterface {
  /**
   * Deletes a dynamically registered OAuth 2.0/OIDC client per RFC 7592. Requires the registration_access_token issued at registration time. Returns 204 No Content on success.
   * @summary Delete a Dynamic Client
   * @param {OIDCApiDeleteDynamicClientRequest} requestParameters Request parameters.
   * @param {*} [options] Override http request option.
   * @throws {RequiredError}
   * @memberof OIDCApi
   */
  public deleteDynamicClient(
    requestParameters: OIDCApiDeleteDynamicClientRequest,
    options?: RawAxiosRequestConfig,
  ) {
    return OIDCApiFp(this.configuration)
      .deleteDynamicClient(requestParameters.oIDCAppName, requestParameters.clientID, options)
      .then((request) => request(this.axios, this.basePath));
  }

  /**
   * Retrieves the metadata of a dynamically registered OAuth 2.0/OIDC client per RFC 7592 (OAuth 2.0 Dynamic Client Registration Management Protocol). Requires the registration_access_token issued at registration time.
   * @summary Get a Dynamic Client
   * @param {OIDCApiGetDynamicClientRequest} requestParameters Request parameters.
   * @param {*} [options] Override http request option.
   * @throws {RequiredError}
   * @memberof OIDCApi
   */
  public getDynamicClient(
    requestParameters: OIDCApiGetDynamicClientRequest,
    options?: RawAxiosRequestConfig,
  ) {
    return OIDCApiFp(this.configuration)
      .getDynamicClient(requestParameters.oIDCAppName, requestParameters.clientID, options)
      .then((request) => request(this.axios, this.basePath));
  }

  /**
   * Returns OAuth 2.0 Authorization Server Metadata (RFC 8414) for the given OIDC app. Use this endpoint for OAuth 2.0 client discovery when using the OIDC flow path. Response does not include OpenID Connect-specific fields (e.g. userinfo_endpoint, claims_supported).
   * @summary OAuth Authorization Server Metadata (OIDC app)
   * @param {OIDCApiGetOAuthAuthorizationServerMetadataOIDCRequest} requestParameters Request parameters.
   * @param {*} [options] Override http request option.
   * @throws {RequiredError}
   * @memberof OIDCApi
   */
  public getOAuthAuthorizationServerMetadataOIDC(
    requestParameters: OIDCApiGetOAuthAuthorizationServerMetadataOIDCRequest,
    options?: RawAxiosRequestConfig,
  ) {
    return OIDCApiFp(this.configuration)
      .getOAuthAuthorizationServerMetadataOIDC(requestParameters.oIDCAppName, options)
      .then((request) => request(this.axios, this.basePath));
  }

  /**
   * Initiates the OAuth 2.0 Device Authorization Grant per RFC 8628. Returns a device_code and user_code that the client displays to the end-user for out-of-band authorization on a secondary device. The client then polls the token endpoint with the device_code until the user completes authorization.
   * @summary Retrieve OIDC device code
   * @param {OIDCApiGetOIDCDeviceCodeRequest} requestParameters Request parameters.
   * @param {*} [options] Override http request option.
   * @throws {RequiredError}
   * @memberof OIDCApi
   */
  public getOIDCDeviceCode(
    requestParameters: OIDCApiGetOIDCDeviceCodeRequest,
    options?: RawAxiosRequestConfig,
  ) {
    return OIDCApiFp(this.configuration)
      .getOIDCDeviceCode(requestParameters.oIDCAppName, requestParameters.oIDCDeviceCode, options)
      .then((request) => request(this.axios, this.basePath));
  }

  /**
   * Returns the OpenID Provider Configuration Information per OpenID Connect Discovery 1.0 (Section 4). Clients use this endpoint to dynamically discover the issuer, supported endpoints, scopes, response types, claims, and signing algorithms. The response includes the authorization_endpoint, token_endpoint, userinfo_endpoint, jwks_uri, and other metadata needed to configure an OIDC Relying Party.
   * @summary OpenID Connect Discovery endpoint
   * @param {OIDCApiGetOIDCDiscoveryConfigRequest} requestParameters Request parameters.
   * @param {*} [options] Override http request option.
   * @throws {RequiredError}
   * @memberof OIDCApi
   */
  public getOIDCDiscoveryConfig(
    requestParameters: OIDCApiGetOIDCDiscoveryConfigRequest,
    options?: RawAxiosRequestConfig,
  ) {
    return OIDCApiFp(this.configuration)
      .getOIDCDiscoveryConfig(requestParameters.oIDCAppName, options)
      .then((request) => request(this.axios, this.basePath));
  }

  /**
   * Retrieves the JSON Web Key Set (JWKS) for verifying token signatures.
   * @summary Retrieve JSON Web Key Set
   * @param {OIDCApiGetOIDCJWKSConfigRequest} requestParameters Request parameters.
   * @param {*} [options] Override http request option.
   * @throws {RequiredError}
   * @memberof OIDCApi
   */
  public getOIDCJWKSConfig(
    requestParameters: OIDCApiGetOIDCJWKSConfigRequest,
    options?: RawAxiosRequestConfig,
  ) {
    return OIDCApiFp(this.configuration)
      .getOIDCJWKSConfig(requestParameters.oIDCAppName, options)
      .then((request) => request(this.axios, this.basePath));
  }

  /**
   * Retrieves OpenID Connect (OIDC) tokens for User authentication.
   * @summary Retrieve OIDC tokens
   * @param {OIDCApiGetOIDCTokensRequest} requestParameters Request parameters.
   * @param {*} [options] Override http request option.
   * @throws {RequiredError}
   * @memberof OIDCApi
   */
  public getOIDCTokens(
    requestParameters: OIDCApiGetOIDCTokensRequest,
    options?: RawAxiosRequestConfig,
  ) {
    return OIDCApiFp(this.configuration)
      .getOIDCTokens(
        requestParameters.oIDCAppName,
        requestParameters.getOAuthTokensRequest,
        options,
      )
      .then((request) => request(this.axios, this.basePath));
  }

  /**
   * Retrieves User information using OpenID Connect (OIDC) standards.
   * @summary Retrieve OIDC User info
   * @param {OIDCApiGetOIDCUserinfoRequest} requestParameters Request parameters.
   * @param {*} [options] Override http request option.
   * @throws {RequiredError}
   * @memberof OIDCApi
   */
  public getOIDCUserinfo(
    requestParameters: OIDCApiGetOIDCUserinfoRequest,
    options?: RawAxiosRequestConfig,
  ) {
    return OIDCApiFp(this.configuration)
      .getOIDCUserinfo(requestParameters.oIDCAppName, options)
      .then((request) => request(this.axios, this.basePath));
  }

  /**
   * Retrieves User information using OpenID Connect (OIDC) standards via the POST method.
   * @summary Retrieve OIDC User info via POST
   * @param {OIDCApiGetOIDCUserinfoByPostRequest} requestParameters Request parameters.
   * @param {*} [options] Override http request option.
   * @throws {RequiredError}
   * @memberof OIDCApi
   */
  public getOIDCUserinfoByPost(
    requestParameters: OIDCApiGetOIDCUserinfoByPostRequest,
    options?: RawAxiosRequestConfig,
  ) {
    return OIDCApiFp(this.configuration)
      .getOIDCUserinfoByPost(requestParameters.oIDCAppName, requestParameters.oIDCUserinfo, options)
      .then((request) => request(this.axios, this.basePath));
  }

  /**
   * Returns the active state and metadata of an OIDC access or refresh token per RFC 7662 (OAuth 2.0 Token Introspection). The client must authenticate using either HTTP Basic authentication (Authorization: Basic base64(client_id:client_secret)) or by including client_id and client_secret in the POST body, depending on the token_endpoint_auth_method configured for the OIDC application. Returns active: true with associated claims for valid tokens, or active: false for invalid, expired, or revoked tokens.
   * @summary Introspect OIDC token
   * @param {OIDCApiIntrospectOIDCTokenRequest} requestParameters Request parameters.
   * @param {*} [options] Override http request option.
   * @throws {RequiredError}
   * @memberof OIDCApi
   */
  public introspectOIDCToken(
    requestParameters: OIDCApiIntrospectOIDCTokenRequest,
    options?: RawAxiosRequestConfig,
  ) {
    return OIDCApiFp(this.configuration)
      .introspectOIDCToken(
        requestParameters.oIDCAppName,
        requestParameters.oAuthRevokeRefreshToken,
        options,
      )
      .then((request) => request(this.axios, this.basePath));
  }

  /**
   * Registers a new OAuth 2.0/OIDC client dynamically per RFC 7591 (OAuth 2.0 Dynamic Client Registration Protocol). The client submits desired metadata (redirect_uris, client_name, grant_types, etc.) and receives the registered client metadata including the assigned client_id and client_secret. This feature must be explicitly enabled on the OIDC application configuration.
   * @summary OIDC dynamic client registration
   * @param {OIDCApiOIDCDynamicClientRegistrationRequest} requestParameters Request parameters.
   * @param {*} [options] Override http request option.
   * @throws {RequiredError}
   * @memberof OIDCApi
   */
  public oIDCDynamicClientRegistration(
    requestParameters: OIDCApiOIDCDynamicClientRegistrationRequest,
    options?: RawAxiosRequestConfig,
  ) {
    return OIDCApiFp(this.configuration)
      .oIDCDynamicClientRegistration(
        requestParameters.oIDCAppName,
        requestParameters.dynamicClientRegistrationRequest,
        options,
      )
      .then((request) => request(this.axios, this.basePath));
  }

  /**
   * Accepts an OIDC authorization request and stores it server-side per RFC 9126 (OAuth 2.0 Pushed Authorization Requests). Returns a short-lived request_uri that the client passes as the sole parameter to the authorization endpoint, keeping all sensitive request parameters out of the browser URL. This feature must be explicitly enabled on the OIDC application configuration.
   * @summary OIDC Pushed Authorization Request (PAR)
   * @param {OIDCApiOIDCPushedAuthorizationRequestRequest} requestParameters Request parameters.
   * @param {*} [options] Override http request option.
   * @throws {RequiredError}
   * @memberof OIDCApi
   */
  public oIDCPushedAuthorizationRequest(
    requestParameters: OIDCApiOIDCPushedAuthorizationRequestRequest,
    options?: RawAxiosRequestConfig,
  ) {
    return OIDCApiFp(this.configuration)
      .oIDCPushedAuthorizationRequest(
        requestParameters.oIDCAppName,
        requestParameters.pARRequest,
        options,
      )
      .then((request) => request(this.axios, this.basePath));
  }

  /**
   * Revokes an OIDC refresh token per RFC 7009 (OAuth 2.0 Token Revocation), invalidating it and preventing any further use. The client must authenticate using client_id and client_secret via HTTP Basic or POST body.
   * @summary Revoke OIDC refresh token
   * @param {OIDCApiRevokeOIDCRefreshTokenRequest} requestParameters Request parameters.
   * @param {*} [options] Override http request option.
   * @throws {RequiredError}
   * @memberof OIDCApi
   */
  public revokeOIDCRefreshToken(
    requestParameters: OIDCApiRevokeOIDCRefreshTokenRequest,
    options?: RawAxiosRequestConfig,
  ) {
    return OIDCApiFp(this.configuration)
      .revokeOIDCRefreshToken(
        requestParameters.oIDCAppName,
        requestParameters.oAuthRevokeRefreshToken,
        options,
      )
      .then((request) => request(this.axios, this.basePath));
  }

  /**
   * Updates the metadata of a dynamically registered OAuth 2.0/OIDC client per RFC 7592. Requires the registration_access_token issued at registration time.
   * @summary Update a Dynamic Client
   * @param {OIDCApiUpdateDynamicClientRequest} requestParameters Request parameters.
   * @param {*} [options] Override http request option.
   * @throws {RequiredError}
   * @memberof OIDCApi
   */
  public updateDynamicClient(
    requestParameters: OIDCApiUpdateDynamicClientRequest,
    options?: RawAxiosRequestConfig,
  ) {
    return OIDCApiFp(this.configuration)
      .updateDynamicClient(
        requestParameters.oIDCAppName,
        requestParameters.clientID,
        requestParameters.oAuthDynamicClientRequest,
        options,
      )
      .then((request) => request(this.axios, this.basePath));
  }
}
